        "properties": {},
        "additionalProperties": true
      },
      "limit": {
        "type": "integer",
        "description": "Root page size. Defaults to 50. Relations have their own page sizes.",
        "minimum": 1
      },
      "cursor": {
        "type": "string",
        "description": "Opaque continuation for the same query over live data; it is not a transaction snapshot."
      },
      "timeoutMs": {
        "type": "integer",
        "description": "Optional caller-selected execution budget in milliseconds. No deadline by default.",
        "minimum": 1
      }
    },
