        "type": "object",
        "description": "View name to UTC ISO-8601 read time; cached data can be older.",
        "properties": {},
        "additionalProperties": true
      },
      "rows": {
        "type": "array",
        "description": "Public projections described by each registered view. Relations contain rows, truncated and nextQuery.",
        "items": {
          "type": "object",
          "properties": {},
          "additionalProperties": true
        }
      },
      "nextCursor": {
        "type": [
          "string",
          "null"
        ],
        "description": "Continuation for the same live query; null when no root continuation is known."
      },
      "truncated": {
        "type": "boolean",
        "description": "True when pagination or a resource limit omitted data."
      },
      "warnings": {
        "type": "array",
